function cleanText(value) {
  return String(value ?? "").trim();
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function pad(value) {
  return String(value).padStart(2, "0");
}

function getTimestamp() {
  const now = new Date();

  return (
    `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_` +
    `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`
  );
}

const data = $json || {};

const BASE_HERRAMIENTA = String.raw`C:\Users\06\Documents\Dropbox\HERRAMIENTAS AUTOMATIZACION\REMISIONES AUDI`;

const logsErrorDir = `${BASE_HERRAMIENTA}\\04_ERRORES`;

const workflowName =
  data.workflow?.name ||
  data.workflowName ||
  "workflow_desconocido";

const executionId =
  data.execution?.id ||
  data.executionId ||
  "";

const nodeName =
  data.execution?.lastNodeExecuted ||
  data.lastNodeExecuted ||
  data.node?.name ||
  data.nodeName ||
  "nodo_desconocido";

const errorMessage =
  data.error?.message ||
  data.message ||
  data.error ||
  "Error no especificado";

const timestamp = getTimestamp();

const logFileName = `ERROR_${safeFileText(workflowName)}_${safeFileText(nodeName)}_${timestamp}.json`;
const logFilePath = `${logsErrorDir}\\${logFileName}`;

const log = {
  tipo_log: "AUDI_ERROR",
  status: "error",

  generated_at: new Date().toISOString(),

  workflow: {
    name: workflowName,
    id: data.workflow?.id || "",
    execution_id: executionId,
    execution_url: data.execution?.url || ""
  },

  error: {
    node: nodeName,
    message: errorMessage,
    stack:
      data.error?.stack ||
      data.stack ||
      ""
  },

  raw_error_data: data
};

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify(log, null, 2), "utf8"),
  logFileName,
  "application/json"
);

return [
  {
    json: {
      log_error_generado: true,
      log_file_name: logFileName,
      log_file_path: logFilePath,
      workflow_name: workflowName,
      node_name: nodeName,
      error_message: errorMessage
    },
    binary: {
      data: binaryData
    }
  }
];
